package agy

import (
	"fmt"
	"strings"
	"sync"

	"github.com/tylergannon/tractor/harness"
	"github.com/tylergannon/tractor/harness/agy/schema"
)

type eventProjector struct {
	emit  harness.OnEvent
	mu    sync.Mutex
	steps map[int]*projectedStep
}

type projectedStep struct {
	text       strings.Builder
	assistant  bool
	toolCall   bool
	toolResult bool
}

func newEventProjector(emit harness.OnEvent) *eventProjector {
	return &eventProjector{emit: emit, steps: make(map[int]*projectedStep)}
}

func (p *eventProjector) user(parts []harness.ContentPart) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.emit(harness.Event{"type": harness.EventUser, "parts": append([]harness.ContentPart(nil), parts...)})
}

func (p *eventProjector) envelope(envelope schema.Envelope) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if envelope.StepUpdate == nil {
		if envelope.Result != nil && envelope.Result.Usage != nil {
			p.emit(harness.Event{"type": harness.EventUsage, "usage": envelope.Result.Usage})
		}
		return
	}
	update := envelope.StepUpdate
	index := 0
	if update.StepIndex != nil {
		index = *update.StepIndex
	}
	step := p.steps[index]
	if step == nil {
		step = &projectedStep{}
		p.steps[index] = step
	}
	typeName, state := stringValue(update.StepType), stringValue(update.State)
	switch typeName {
	case "agent_response":
		if update.TextDelta != nil {
			step.text.WriteString(*update.TextDelta)
		}
		if state == "DONE" && !step.assistant {
			step.assistant = true
			if text := step.text.String(); strings.TrimSpace(text) != "" {
				p.emit(harness.Event{"type": harness.EventAssistant, "text": text})
			}
		}
		if state == "DONE" && update.Usage != nil {
			p.emit(harness.Event{"type": harness.EventUsage, "usage": update.Usage})
		}
	case "tool":
		info := update.ToolInfo
		if info == nil {
			return
		}
		callID := fmt.Sprintf("step-%d", index)
		if !step.toolCall && info.Name != nil {
			step.toolCall = true
			p.emit(harness.Event{"type": harness.EventToolCall, "call_id": callID, "name": *info.Name, "args": info.Parameters})
		}
		if state == "DONE" && !step.toolResult {
			step.toolResult = true
			output := info.Output
			if info.Error != nil {
				output = map[string]any{"output": info.Output, "error": info.Error}
			}
			p.emit(harness.Event{"type": harness.EventToolResult, "call_id": callID, "output": output})
		}
	}
}

func stringValue(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

package engine

import (
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/tylergannon/tractor/graph"
)

// BranchArtifact is one declared branch output exposed to fan-in and later
// stages. Path is stable run evidence in isolated mode and the live workspace
// path in shared mode.
type BranchArtifact struct {
	Declared string `json:"declared"`
	Path     string `json:"path"`
	Source   string `json:"source,omitempty"`
}

func (h *parallelHandler) collectArtifacts(stageDir string, parallel *graph.ParallelNode, results []BranchResult) {
	for index := range results {
		result := &results[index]
		if result.Error != nil {
			continue
		}
		branch, ok := parallel.Branch(result.BranchID)
		if !ok || branch.IsLegacy() {
			continue
		}
		result.Workspace = string(parallel.WorkspacePolicyValue())
		for _, declared := range branch.Artifacts {
			artifact, err := collectBranchArtifact(stageDir, parallel.WorkspacePolicyValue(), *result, declared)
			if err != nil {
				result.Outcome = nil
				result.Error = terminalError(fmt.Sprintf("collect artifact %q for branch %q: %v", declared, result.BranchID, err))
				break
			}
			result.Artifacts = append(result.Artifacts, artifact)
		}
	}
}

func collectBranchArtifact(stageDir string, policy graph.WorkspacePolicy, result BranchResult, declared string) (BranchArtifact, error) {
	source := filepath.Join(result.Workdir, filepath.Clean(declared))
	info, err := os.Lstat(source)
	if err != nil {
		return BranchArtifact{}, err
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return BranchArtifact{}, fmt.Errorf("symbolic links are not supported")
	}
	if policy == graph.WorkspaceShared {
		return BranchArtifact{Declared: declared, Path: source}, nil
	}
	target := filepath.Join(stageDir, "artifacts", result.BranchID, filepath.Clean(declared))
	if err := copyArtifact(source, target, info); err != nil {
		return BranchArtifact{}, err
	}
	return BranchArtifact{Declared: declared, Path: target, Source: source}, nil
}

func copyArtifact(source, target string, info os.FileInfo) error {
	if info.IsDir() {
		if err := os.MkdirAll(target, info.Mode().Perm()); err != nil {
			return err
		}
		entries, err := os.ReadDir(source)
		if err != nil {
			return err
		}
		for _, entry := range entries {
			entrySource := filepath.Join(source, entry.Name())
			entryInfo, err := os.Lstat(entrySource)
			if err != nil {
				return err
			}
			if entryInfo.Mode()&os.ModeSymlink != 0 {
				return fmt.Errorf("symbolic links are not supported: %s", entrySource)
			}
			if err := copyArtifact(entrySource, filepath.Join(target, entry.Name()), entryInfo); err != nil {
				return err
			}
		}
		return nil
	}
	if !info.Mode().IsRegular() {
		return fmt.Errorf("unsupported artifact file mode %s", info.Mode())
	}
	if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
		return err
	}
	input, err := os.Open(source)
	if err != nil {
		return err
	}
	defer func() { _ = input.Close() }()
	output, err := os.OpenFile(target, os.O_CREATE|os.O_EXCL|os.O_WRONLY, info.Mode().Perm())
	if err != nil {
		return err
	}
	if _, err := io.Copy(output, input); err != nil {
		_ = output.Close()
		return err
	}
	return output.Close()
}

package engine

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	jsonschema "github.com/tylergannon/go-gen-jsonschema"
	"github.com/tylergannon/tractor/graph"
	"github.com/tylergannon/tractor/harness"
)

// CodergenConfig supplies the backend and implementation-level model defaults.
type CodergenConfig struct {
	Backend                harness.CodergenBackend
	DefaultModel           string
	DefaultProvider        string
	DefaultReasoningEffort string
}

// CodergenHandler executes codergen nodes through a CodergenBackend.
type CodergenHandler struct {
	config CodergenConfig
}

// NewCodergenHandler constructs a codergen handler. A nil backend enables simulation.
func NewCodergenHandler(config CodergenConfig) *CodergenHandler {
	return &CodergenHandler{config: config}
}

// Execute renders and executes one codergen turn.
func (h *CodergenHandler) Execute(node graph.Node, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph) (harness.Outcome, *harness.Error) {
	codergen, ok := node.(*graph.CodergenNode)
	if !ok {
		return harness.Outcome{}, terminalError(fmt.Sprintf("codergen handler cannot execute node type %s", node.NodeType()))
	}

	prompt := codergen.PromptValue(codergen.DisplayLabel())
	prompt = expandPrompt(prompt, scope.Goal)
	return h.executeTurn(codergen, &codergen.LLMNodeFields, offered, scope, pipeline, prompt)
}

func (h *CodergenHandler) executeTurn(node graph.Node, fields *graph.LLMNodeFields, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph, prompt string) (harness.Outcome, *harness.Error) {
	if err := os.WriteFile(filepath.Join(scope.StageDir, "prompt.md"), []byte(prompt), 0o644); err != nil {
		return harness.Outcome{}, terminalError(fmt.Sprintf("write prompt: %v", err))
	}

	turn, err := h.turn(node, fields, offered, scope, pipeline, prompt)
	if err != nil {
		return harness.Outcome{}, err
	}
	validationTurn := turn
	if h.config.Backend == nil && validationTurn.RunLog == "" {
		validationTurn.RunLog = filepath.Join(scope.StageDir, "simulation.jsonl")
	}
	if validationErr := harness.ValidateCodergenTurn(validationTurn); validationErr != nil {
		return harness.Outcome{}, validationErr
	}
	if codergen, ok := node.(*graph.CodergenNode); ok && codergen.IsSynthesized() {
		if err := writeJSON(filepath.Join(scope.StageDir, "resolved.json"), resolvedCodergenRecord{
			Type:            "codergen",
			ID:              node.Base().ID,
			Prompt:          prompt,
			Provider:        validationTurn.Provider,
			Model:           validationTurn.Model,
			ReasoningEffort: validationTurn.ReasoningEffort,
			Fidelity:        validationTurn.Fidelity,
			ThreadID:        validationTurn.ThreadKey,
			Timeout:         validationTurn.Timeout.String(),
			Workdir:         validationTurn.Workdir,
			RunLog:          validationTurn.RunLog,
		}); err != nil {
			return harness.Outcome{}, terminalError(fmt.Sprintf("write resolved Codergen configuration: %v", err))
		}
	}
	var outcome harness.Outcome
	if h.config.Backend == nil {
		outcome = harness.Outcome{Notes: "[Simulated] Stage completed: " + node.Base().ID}
		if len(offered) > 1 {
			outcome.Next = offered[0].To
		}
	} else {
		var runErr *harness.Error
		outcome, runErr = h.config.Backend.Run(turn)
		if runErr != nil {
			return harness.Outcome{}, runErr
		}
	}

	if err := writeResponse(filepath.Join(scope.StageDir, "response.md"), outcome); err != nil {
		return harness.Outcome{}, terminalError(fmt.Sprintf("write response: %v", err))
	}
	return outcome, nil
}

type resolvedCodergenRecord struct {
	Type            string               `json:"type"`
	ID              string               `json:"id"`
	Prompt          string               `json:"prompt"`
	Provider        string               `json:"llm_provider"`
	Model           string               `json:"llm_model"`
	ReasoningEffort string               `json:"reasoning_effort"`
	Fidelity        harness.FidelityMode `json:"fidelity"`
	ThreadID        string               `json:"thread_id,omitempty"`
	Timeout         string               `json:"timeout"`
	Workdir         string               `json:"workdir"`
	RunLog          string               `json:"run_log"`
}

func (h *CodergenHandler) turn(node graph.Node, fields *graph.LLMNodeFields, offered []graph.Edge, scope ExecutionScope, pipeline *graph.Graph, prompt string) (harness.CodergenTurn, *harness.Error) {
	model := resolveString(fields.LLMModel, pipeline.Defaults.LLMModel, h.config.DefaultModel)
	provider := resolveProvider(fields.LLMProvider, pipeline.Defaults.LLMProvider, h.config.DefaultProvider, model)
	reasoningDefault := h.config.DefaultReasoningEffort
	if reasoningDefault == "" {
		reasoningDefault = "high"
	}
	reasoning := resolveString(fields.ReasoningEffort, pipeline.Defaults.ReasoningEffort, reasoningDefault)
	fidelity := resolveString(fields.Fidelity, pipeline.Defaults.Fidelity, string(harness.FidelityCompacted))
	threadKey := ""
	if fidelity != string(harness.FidelityNone) {
		threadKey = fields.ThreadKey(node.Base().ID)
	}
	timeout, timeoutErr := resolveTimeout(fields.Timeout, pipeline.Defaults.Timeout)
	if timeoutErr != nil {
		return harness.CodergenTurn{}, terminalError(timeoutErr.Error())
	}
	schema, schemaErr := choiceSchema(offered, pipeline)
	if schemaErr != nil {
		return harness.CodergenTurn{}, terminalError(schemaErr.Error())
	}
	return harness.CodergenTurn{
		NodeID:          node.Base().ID,
		Parts:           []harness.ContentPart{{Type: harness.ContentPartText, Text: prompt}},
		OutputSchema:    schema,
		Model:           model,
		Provider:        provider,
		ReasoningEffort: reasoning,
		Fidelity:        harness.FidelityMode(fidelity),
		ThreadKey:       threadKey,
		Workdir:         scope.Workdir,
		RunLog:          scope.RunLog,
		Timeout:         timeout,
	}, nil
}

func resolveString(nodeValue, fileValue jsonschema.Optional[string], systemValue string) string {
	if nodeValue.Present {
		return nodeValue.Value
	}
	if fileValue.Present {
		return fileValue.Value
	}
	return systemValue
}

func resolveProvider(nodeValue, fileValue jsonschema.Optional[string], systemValue, model string) string {
	if nodeValue.Present {
		return nodeValue.Value
	}
	if fileValue.Present {
		return fileValue.Value
	}
	if systemValue != "" {
		return systemValue
	}
	return DetectProvider(model)
}

func resolveTimeout(nodeValue, fileValue jsonschema.Optional[graph.Duration]) (time.Duration, error) {
	if nodeValue.Present {
		return nodeValue.Value.Parse()
	}
	if fileValue.Present {
		return fileValue.Value.Parse()
	}
	return 0, nil
}

// DetectProvider returns the provider implied by a known provider-native model name.
func DetectProvider(model string) string {
	lower := strings.ToLower(model)
	switch {
	case strings.HasPrefix(lower, "claude"):
		return "anthropic"
	case strings.HasPrefix(lower, "gpt-"), strings.HasPrefix(lower, "o1"), strings.HasPrefix(lower, "o3"), strings.HasPrefix(lower, "o4"), strings.Contains(lower, "codex"):
		return "openai"
	case strings.HasPrefix(lower, "gemini"):
		return "gemini"
	default:
		return ""
	}
}

type outputSchema struct {
	Type                 string           `json:"type"`
	Properties           schemaProperties `json:"properties"`
	Required             []string         `json:"required"`
	AdditionalProperties bool             `json:"additionalProperties"`
}

type schemaProperties struct {
	Next  *schemaProperty `json:"next,omitempty"`
	Notes schemaProperty  `json:"notes"`
}

type schemaProperty struct {
	Type        string   `json:"type"`
	Enum        []string `json:"enum,omitempty"`
	Description string   `json:"description"`
}

func choiceSchema(offered []graph.Edge, pipeline *graph.Graph) (json.RawMessage, error) {
	properties := schemaProperties{
		Notes: schemaProperty{Type: "string", Description: "Your account of this stage."},
	}
	required := []string{"notes"}
	if len(offered) > 1 {
		targets := make([]string, len(offered))
		for index, edge := range offered {
			targets[index] = edge.To
		}
		properties.Next = &schemaProperty{
			Type:        "string",
			Enum:        targets,
			Description: describeRoutes(offered, pipeline),
		}
		required = []string{"next", "notes"}
	}
	encoded, err := json.Marshal(outputSchema{
		Type:                 "object",
		Properties:           properties,
		Required:             required,
		AdditionalProperties: false,
	})
	if err != nil {
		return nil, fmt.Errorf("encode choice schema: %w", err)
	}
	return encoded, nil
}

func describeRoutes(offered []graph.Edge, pipeline *graph.Graph) string {
	clauses := make([]string, len(offered))
	for index, edge := range offered {
		description := strings.TrimSpace(edge.Condition)
		if description == "" {
			if target, ok := pipeline.NodeByID(edge.To); ok {
				description = strings.TrimSpace(target.Base().DisplayLabel())
			}
			if description == "" {
				description = edge.To
			}
		}
		clauses[index] = description + ": " + edge.To
	}
	return "Choose the next stage. " + strings.Join(clauses, "; ")
}

func writeResponse(path string, outcome harness.Outcome) error {
	var response strings.Builder
	response.WriteString("---\n")
	if outcome.Next != "" {
		response.WriteString("next: ")
		response.WriteString(outcome.Next)
		response.WriteByte('\n')
	}
	response.WriteString("---\n")
	response.WriteString(outcome.Notes)
	return os.WriteFile(path, []byte(response.String()), 0o644)
}

