		}
	})
	if runErr != nil {
		t.Fatal(runErr)
	}
	if users != 1 || len(readInvocations(t, record)) != 1 {
		t.Fatalf("inactive steering leaked: users=%d invocations=%d", users, len(readInvocations(t, record)))
	}
}

